import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:mobile_slice/engine/profile_catalog.dart';
import 'package:mobile_slice/engine/profile_values.dart';
import 'package:mobile_slice/engine/setting_defs.dart';

typedef OrcaKey = ({String type, List<String> enums});

/// Keys and enum values of the pinned engine (generated by tool/gen_orca_keys.py).
Map<String, OrcaKey> orcaKeys() => {
      for (final line in File('test/engine/orca_keys.txt').readAsLinesSync())
        if (line.isNotEmpty && !line.startsWith('#'))
          line.split('\t')[0]: (
            type: line.split('\t')[1],
            enums: line.split('\t')[2].isEmpty ? const <String>[] : line.split('\t')[2].split(','),
          ),
    };

ProfileCatalog bundledCatalog() => ProfileCatalog.fromJson(
      jsonDecode(File('assets/engine/profiles/catalog.json').readAsStringSync()) as Map<String, Object?>,
    );

ProfileValues bundledValues(ProfileCatalog catalog) {
  ProfileMap read(String file) =>
      (jsonDecode(File('assets/engine/profiles/$file').readAsStringSync()) as Map).cast<String, Object?>();
  return ProfileValues(
    processes: {for (final p in catalog.processes) p.id: read(p.file)},
    filaments: {for (final f in catalog.filaments) f.id: read(f.file)},
    printer: read('printer.json'),
  );
}

const _compatible = {
  SettingKind.integer: {'coInt', 'coInts', 'coFloat', 'coFloats'},
  SettingKind.decimal: {'coFloat', 'coFloats', 'coFloatOrPercent', 'coFloatsOrPercents'},
  SettingKind.percent: {'coPercent', 'coPercents', 'coFloatOrPercent'},
  SettingKind.toggle: {'coBool', 'coBools'},
  SettingKind.choice: {'coEnum', 'coEnums'},
};

/// Asserts that [key] = [value] is something the engine accepts.
void expectValidValue(Map<String, OrcaKey> keys, String key, Object? value) {
  final orca = keys[key];
  expect(orca, isNotNull, reason: 'unbekannter Schlüssel $key');
  final def = settingDef(key);
  expect(def, isNotNull, reason: '$key fehlt in settingDefs');
  expect(normalizeSettingValue(def!, value), isNotNull, reason: '$key: falscher Typ $value');
  if (def.kind == SettingKind.choice && orca!.enums.isNotEmpty) {
    expect(orca.enums, contains(value), reason: '$key: ungültiger Wert $value');
  }
}

void main() {
  final keys = orcaKeys();
  final catalog = bundledCatalog();
  final values = bundledValues(catalog);

  test('rund 120 Einstellungen in 11 Kategorien, jede Kategorie gefüllt', () {
    expect(settingDefs.length, greaterThanOrEqualTo(110));
    expect(settingsByKey.length, settingDefs.length, reason: 'doppelte Schlüssel');
    expect(SettingCategory.values, hasLength(11));
    for (final category in SettingCategory.values) {
      expect(settingsIn(category).where((d) => !d.advanced), isNotEmpty, reason: '${category.label} ohne Basisoption');
    }
  });

  test('jeder Schlüssel existiert in der Engine und passt zum Typ', () {
    for (final def in settingDefs) {
      final orca = keys[def.key];
      expect(orca, isNotNull, reason: 'unbekannter Schlüssel ${def.key}');
      expect(_compatible[def.kind], contains(orca!.type), reason: '${def.key}: ${def.kind} passt nicht zu ${orca.type}');
      expect(def.source == SettingSource.filament, orca.type.endsWith('s'), reason: '${def.key}: Quelle passt nicht');
      if (def.printerFallback != null) expect(keys, contains(def.printerFallback), reason: def.key);
    }
  });

  test('jeder Auswahlwert ist gültig', () {
    for (final def in settingDefs.where((d) => d.kind == SettingKind.choice)) {
      expect(def.choices, isNotEmpty, reason: def.key);
      for (final choice in def.choices) {
        expectValidValue(keys, def.key, choice.value);
      }
    }
  });

  test('Grenzen, Abhängigkeiten und Standardwerte sind stimmig', () {
    for (final def in settingDefs) {
      expect(def.min, lessThan(def.max), reason: def.key);
      expect(def.help.length, greaterThan(10), reason: def.key);
      if (def.engineDefault != null) expect(normalizeSettingValue(def, def.engineDefault), isNotNull, reason: def.key);
      final showIf = def.showIf;
      if (showIf != null) {
        final other = settingDef(showIf.key);
        expect(other, isNotNull, reason: '${def.key} hängt an ${showIf.key}');
        for (final v in [...showIf.any, ...showIf.not]) {
          expect(normalizeSettingValue(other!, v), v, reason: '${def.key}: $v');
        }
      }
    }
  });

  test('jedes Profil liefert für jede Einstellung einen Wert', () {
    for (final process in catalog.processes) {
      for (final filament in catalog.filaments) {
        for (final def in settingDefs) {
          final value = values.profileValue(def, processId: process.id, filamentId: filament.id);
          expect(value, isNotNull, reason: '${def.key} in ${process.id}/${filament.id}');
          expect(normalizeSettingValue(def, value), value, reason: def.key);
        }
      }
    }
  });

  test('Profilwerte werden richtig gelesen', () {
    Object? v(String key, {String filament = 'generic-pla'}) =>
        values.profileValue(settingDef(key)!, processId: '0.20', filamentId: filament);
    expect(v('sparse_infill_density'), 15.0);
    expect(v('wall_loops'), 2);
    expect(v('enable_support'), false);
    expect(v('seam_position'), 'aligned');
    expect(v('nozzle_temperature'), 220);
    expect(v('fuzzy_skin'), 'none');
    expect(v('fuzzy_skin_thickness'), 0.2);
    // "nil" im Filament fällt auf den Drucker zurück, TPU hat einen eigenen Wert.
    expect(v('filament_retraction_length'), 0.8);
    expect(v('filament_retraction_length', filament: 'generic-tpu'), 0.4);
  });

  test('Werte parsen', () {
    final percent = settingDef('sparse_infill_density')!;
    expect(parseSettingValue(percent, '15%'), 15.0);
    expect(parseSettingValue(settingDef('enable_support')!, '1'), true);
    expect(parseSettingValue(settingDef('nozzle_temperature')!, ['230']), 230);
    expect(parseSettingValue(settingDef('filament_z_hop')!, ['nil']), isNull);
    expect(parseSettingValue(percent, 'kaputt'), isNull);
  });
}
